inputs.script:
const {apikey} = input.config();
const workspaces = await base.getTable('Workspace IDs').selectRecordsAsync({fields:['Status','ID']});
const existing = await base.getTable('Campaigns').selectRecordsAsync({fields:['ID','end_date','Status Last Modified']});
const tracked = new Map(existing.records.map(r => [Number(r.getCellValue('ID')),r]));
const today = Date.parse(new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()));
function eligible(c) {
  if (c.status === 'active') return true;
  const r = tracked.get(Number(c.id));
  if (!r) return false;
  if (!['paused','inactive','completed'].includes(String(c.status).toLowerCase())) return true;
  const raw = r.getCellValue('end_date') || r.getCellValue('Status Last Modified');
  const day = raw ? Date.parse(String(raw).slice(0,10)) : NaN;
  return Number.isFinite(day) && today-day <= 30*86400000;
}
const combined = new Map();
const failures = [];
for (const record of workspaces.records.filter(r => r.getCellValue('Status')?.name === 'Active')) {
  const workspaceID = record.getCellValue('ID');
  if (!workspaceID) continue;
  try {
    const switched = await fetch('https://send.dulcy.io/api/workspaces/switch-workspace', {method:'POST',headers:{Authorization:'Bearer '+apikey,'Content-Type':'application/json'},body:JSON.stringify({team_id:workspaceID})});
    if (!switched.ok) throw new Error('Workspace switch HTTP '+switched.status);
    let page=1;
    while (true) {
      const response = await fetch('https://send.dulcy.io/api/campaigns?page='+page, {headers:{Authorization:'Bearer '+apikey}});
      if (!response.ok) throw new Error('Campaign page '+page+' HTTP '+response.status);
      const result = await response.json();
      if (!Array.isArray(result.data)) throw new Error('Invalid campaign response');
      for (const c of result.data) {
        if (eligible(c)) combined.set(workspaceID+':'+c.id,{...c,workspaceID});
      }
      const last = Number(result.meta?.last_page);
      if (Number.isFinite(last) && last>=1) { if (page>=last) break; }
      else if (!result.links?.next) break;
      page++;
      if (page>100) throw new Error('Pagination limit exceeded');
    }
  } catch (error) { failures.push('Workspace '+workspaceID+': '+error.message); }
}
if (failures.length) throw new Error('Sync incomplete: '+failures.join('; '));
output.set('campaignDetails',JSON.stringify([...combined.values()]));
console.log('Fetched '+combined.size+' campaigns, using the 30-day inactive/completed cutoff.');

const inputData = input.config(); // Fetch input data
const apiKey = inputData.apikey; // API key passed in as an input
let campaignDetails = inputData.campaignDetails; // Array of campaign details from the script output
const table = base.getTable("Campaigns"); // Replace "Campaigns" with your Airtable table name

console.log("Input Data:", inputData); // Log input data for debugging

// Ensure campaignDetails is an array by parsing it if necessary
if (typeof campaignDetails === "string") {
    try {
        campaignDetails = JSON.parse(campaignDetails); // Parse the string into a JSON array
    } catch (error) {
        console.error("Error parsing campaignDetails:", error);
        throw new Error("campaignDetails is not a valid JSON array.");
    }
}

// Check if campaignDetails is a valid array
if (!Array.isArray(campaignDetails) || campaignDetails.length === 0) {
    console.error("Campaign Details is empty or not in the correct format.");
    throw new Error("Campaign Details is empty or invalid.");
}

(async function main() {
    try {
        // Fetch all existing records in the table
        const existingRecords = await table.selectRecordsAsync();

        for (const campaign of campaignDetails) {
            try {
                // Reformat created_at and updated_at to ensure proper ISO 8601 format
                campaign.created_at = new Date(campaign.created_at).toISOString();
                campaign.updated_at = new Date(campaign.updated_at).toISOString();

                // Check if the campaign already exists in the table
                const existingRecord = existingRecords.records.find(
                    record => record.getCellValue("ID") === campaign.id
                );

                if (existingRecord) {
                    // Update the existing record
                    await table.updateRecordAsync(existingRecord.id, {
                        "Name": campaign.name,
                        "Emails Sent": campaign.emails_sent,
                        "Unique Replies": campaign.unique_replies,
                        "Progress": campaign.completion_percentage/100,
                        "Bounced": campaign.bounced,
                        "Interested": campaign.interested,
                        "Total Leads Contacted": campaign.total_leads_contacted,
                        "Total Leads Remaining": campaign.total_leads-campaign.total_leads_contacted,
                        "Updated At": campaign.updated_at,
                        "Total Leads": campaign.total_leads
                    });
                    console.log(`Updated record for campaign: ${campaign.name}`);
                } else {
                    // Create a new record
                    await table.createRecordAsync({
                        "ID": campaign.id,
                        "Name": campaign.name,
                        "Total Leads": campaign.total_leads,
                        "Emails Sent": campaign.emails_sent,
                        "Unique Replies": campaign.unique_replies,
                        "Progress": campaign.completion_percentage/100,
                        "Bounced": campaign.bounced,
                        "Interested": campaign.interested,
                        "Total Leads Contacted": campaign.total_leads_contacted,
                        "Total Leads Remaining": campaign.total_leads-campaign.total_leads_contacted,
                        "Updated At": campaign.updated_at,
                    });
                    console.log(`Created record for campaign: ${campaign.name}`);
                }
            } catch (error) {
                console.error(`Error processing campaign ${campaign.name}:`, error.message || error);
            }
        }
    } catch (error) {
        console.error("Error fetching existing records or processing campaigns:", error.message || error);
    }
})();
